import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

# Custom HIP kernel for Softmax + 2x MaxPool3d
# For each (batch, channel, d_out, h_out, w_out), compute the max of the 4x4x4 softmax values.
# To compute each softmax value, we need the sum of exp across all channels for that spatial position.

softmax_maxpool_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <algorithm>

__global__ void softmax_maxpool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int in_d, int in_h, int in_w,
    int out_d, int out_h, int out_w) 
{
    // Each thread handles one (batch, d_out, h_out, w_out) and computes all channels
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_spatial_out = batch_size * out_d * out_h * out_w;

    if (idx < total_spatial_out) {
        int w_out_idx = idx % out_w;
        int h_out_idx = (idx / out_w) % out_h;
        int d_out_idx = (idx / (out_w * out_h)) % out_d;
        int b_idx = idx / (out_w * out_h * out_d);

        // Output max values for each channel
        float max_vals[16]; // assuming channels is 16 as in the model
        for (int c = 0; c < 16; ++c) {
            max_vals[c] = -1.0e30f;
        }

        for (int i = 0; i < 4; ++i) {
            int d_in_idx = d_out_idx * 4 + i;
            if (d_in_idx >= in_d) continue;

            for (int j = 0; j < 4; ++j) {
                int h_in_idx = h_out_idx * 4 + j;
                if (h_in_idx >= in_h) continue;

                for (int k = 0; k < 4; ++k) {
                    int w_in_idx = w_out_idx * 4 + k;
                    if (w_in_idx >= in_w) continue;

                    // Now at a specific spatial location (b_idx, d_in_idx, h_in_idx, w_in_idx)
                    // Compute Softmax across all 16 channels
                    float channel_vals[16];
                    float max_c = -1.0e30f;

                    for (int c = 0; c < 16; ++c) {
                        int in_idx = (((b_idx * channels + c) * in_d + d_in_idx) * in_h + h_in_idx) * in_w + w_in_idx;
                        float val = input[in_idx];
                        channel_vals[c] = val;
                        if (val > max_c) max_c = val;
                    }

                    float sum_exp = 0.0f;
                    for (int c = 0; c < 16; ++c) {
                        channel_vals[c] = expf(channel_vals[c] - max_c);
                        sum_exp += channel_vals[c];
                    }

                    float inv_sum_exp = 1.0f / sum_exp;
                    for (int c = 0; c < 16; ++c) {
                        float softmax_val = channel_vals[c] * inv_sum_exp;
                        if (softmax_val > max_vals[c]) {
                            max_vals[c] = softmax_val;
                        }
                    }
                }
            }
        }

        // Store results
        for (int c = 0; c < 16; ++c) {
            int out_idx = (((b_idx * channels + c) * out_d + d_out_idx) * out_h + h_out_idx) * out_w + w_out_idx;
            output[out_idx] = max_vals[c];
        }
    }
}

torch::Tensor softmax_maxpool_hip(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto in_d = input.size(2);
    auto in_h = input.size(3);
    auto in_w = input.size(4);

    // MaxPool3d(2) then MaxPool3d(2)
    int out_d = ((in_d / 2) / 2);
    int out_h = ((in_h / 2) / 2);
    int out_w = ((in_w / 2) / 2);

    auto output = torch::empty({batch_size, channels, out_d, out_h, out_w}, input.options());

    int total_spatial_out = batch_size * out_d * out_h * out_w;
    int block_size = 256;
    int num_blocks = (total_spatial_out + block_size - 1) / block_size;

    softmax_maxpool_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, channels, in_d, in_h, in_w, out_d, out_h, out_w
    );

    return output;
}
"""

softmax_maxpool = load_inline(
    name="softmax_maxpool",
    cpp_sources=softmax_maxpool_source,
    functions=["softmax_maxpool_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size).cuda()
        self.softmax_maxpool = softmax_maxpool

    def forward(self, x):
        x = self.conv(x)
        x = self.softmax_maxpool.softmax_maxpool_hip(x)
        return x

