        output[out_base_idx_f4 + 2] = make_float4(max_vals[8], max_vals[9], max_vals[10], max_vals[11]);
        output[out_base_idx_f4 + 3] = make_float4(max_vals[12], max_vals[13], max_vals[14], max_vals[15]);
    }
