    // Note: This only works if we're only looking at the first 16 threads in a 16-thread group.
    // The value will be correct in the first thread of the 16-thread group.
    return __shfl(val, 0, 16);
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 8; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset, 16);
    }
    return __shfl(val, 0, 16);
}

