                if (h_in_idx >= in_h) continue;
                for (int k = 0; k < 4; ++k) {
                    int w_in_idx = w_out_idx * 4 + k;
                    if (w_in_idx >= in_w) continue;

                    int in_idx = (((b_idx * in_d + d_in_idx) * in_h + h_in_idx) * in_w + w_in_idx) * 16 + c_idx;
